#!/usr/bin/env python3
"""Run once in Codespace: python3 install_app.py && git add -A && git commit -m "Fix app" && git push origin main"""
import base64, json, zlib
from pathlib import Path
_BUNDLE = ""
def main():
    files = json.loads(zlib.decompress(base64.b64decode(_BUNDLE)))
    for rel, text in files.items():
        p = Path(rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(text)
        print("Wrote", rel)
    print("Done. Now: git add -A && git commit -m \"Fix app\" && git push origin main")
if __name__ == "__main__":
    main()
